<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{Bot,BrainCircuit,CheckCircle2,FileSearch,GitBranch,Lightbulb,Play,RefreshCw,Search,ShieldCheck,Sparkles}from'lucide-vue-next';import{useAuthStore}from'@/stores/useAuthStore';import{confidenceTone,riskLabel}from'@/features/aiops/aiopsModel';type Evidence={type:string;title:string;detail:string;weight:number};type Recommendation={runbookId:string;title:string;risk:string;impact:string;duration:string;steps:string[]};type Analysis={id:string;alertId:string;title:string;severity:string;target:string;rootCause:string;confidence:number;summary:string;createdAt:string;evidence:Evidence[];recommendations:Recommendation[]};type Knowledge={id:string;title:string;category:string;summary:string;tags:string[];helpful:number};type Execution={id:string;status:string;requestedAt:string};type Summary={openAnomalies:number;analyzedToday:number;accuracy:number;knowledgeCount:number;pendingActions:number};const auth=useAuthStore(),summary=ref<Summary>(),analyses=ref<Analysis[]>([]),knowledge=ref<Knowledge[]>([]),executions=ref<Execution[]>([]),selected=ref<Analysis>(),query=ref(''),tab=ref<'analysis'|'knowledge'>('analysis'),message=ref('');const headers=computed(()=>({Authorization:`Bearer ${auth.token}`,'Content-Type':'application/json'}));async function load(){[summary.value,analyses.value,knowledge.value,executions.value]=await Promise.all(['summary','analyses','knowledge','executions'].map(x=>fetch('/api/v1/aiops/'+x,{headers:headers.value}).then(r=>r.json())));selected.value ||= analyses.value[0]}async function search(){const r=await fetch('/api/v1/aiops/knowledge?q='+encodeURIComponent(query.value),{headers:headers.value});knowledge.value=await r.json()}async function execute(rec:Recommendation){if(!selected.value)return;const r=await fetch(`/api/v1/aiops/analyses/${selected.value.id}/execute`,{method:'POST',headers:headers.value,body:JSON.stringify({runbookId:rec.runbookId})});const x=await r.json();message.value=`执行申请 ${x.id} 已提交，等待人工审批`;await load()}onMounted(load)</script>
<template><section class="aiops-page"><header class="aiops-heading"><div><span>AI-ASSISTED OPERATIONS</span><h1>AIOps 智能运维中心</h1><p>基于指标、日志、变更与拓扑证据的异常归因</p></div><button @click="load"><RefreshCw/>刷新分析</button></header><div class="aiops-summary"><article><BrainCircuit/><span>待处理异常<strong>{{summary?.openAnomalies}}</strong></span></article><article><Sparkles/><span>今日分析<strong>{{summary?.analyzedToday}}</strong></span></article><article><ShieldCheck/><span>归因准确率<strong>{{summary?.accuracy}}%</strong></span></article><article><FileSearch/><span>知识条目<strong>{{summary?.knowledgeCount}}</strong></span></article><article><Play/><span>待审批动作<strong>{{summary?.pendingActions}}</strong></span></article></div><nav class="aiops-tabs"><button :class="{active:tab==='analysis'}" @click="tab='analysis'">智能分析</button><button :class="{active:tab==='knowledge'}" @click="tab='knowledge'">知识库</button></nav><div v-if="tab==='analysis'" class="aiops-workspace"><aside class="analysis-list"><button v-for="a in analyses" :key="a.id" :class="{active:selected?.id===a.id}" @click="selected=a"><i :data-severity="a.severity"></i><div><strong>{{a.title}}</strong><span>{{a.target}} · {{a.createdAt}}</span></div><b :data-tone="confidenceTone(a.confidence)">{{a.confidence}}%</b></button></aside><main v-if="selected" class="analysis-detail"><header><div><span>ROOT CAUSE ANALYSIS</span><h2>{{selected.rootCause}}</h2><p>{{selected.summary}}</p></div><div class="confidence-ring" :style="{'--score':selected.confidence+'%'}"><strong>{{selected.confidence}}%</strong><span>置信度</span></div></header><h3><GitBranch/>归因证据链</h3><div class="evidence-grid"><article v-for="e in selected.evidence" :key="e.title"><header><b>{{e.type}}</b><strong>{{e.weight}}%</strong></header><h4>{{e.title}}</h4><p>{{e.detail}}</p><div><i :style="{width:e.weight+'%'}"></i></div></article></div><h3><Lightbulb/>推荐 Runbook</h3><article v-for="r in selected.recommendations" :key="r.runbookId" class="runbook"><header><div><strong>{{r.title}}</strong><span>{{riskLabel(r.risk)}} · {{r.duration}}</span></div><b>{{r.impact}}</b></header><ol><li v-for="step in r.steps" :key="step">{{step}}</li></ol><footer><span><ShieldCheck/>所有操作需要人工审批并完整审计</span><button class="primary" @click="execute(r)"><Play/>申请受控执行</button></footer></article><div v-if="message" class="aiops-message"><CheckCircle2/>{{message}}</div></main></div><div v-else class="knowledge-page"><form @submit.prevent="search"><Search/><input v-model="query" placeholder="搜索故障现象、技术栈或关键词"><button>检索知识</button></form><div class="knowledge-grid"><article v-for="k in knowledge" :key="k.id"><b>{{k.category}}</b><h3>{{k.title}}</h3><p>{{k.summary}}</p><div><span v-for="tag in k.tags" :key="tag">{{tag}}</span></div><footer>{{k.helpful}} 次解决问题</footer></article></div></div></section></template>
